/* From Uiverse.io by WhiteNervosa - Tags: checkbox, radio */
/* Variation of work by @mrhyddenn for Radios */


.__UIV_SCOPE__ .check {
  cursor: pointer;
  position: relative;
  margin: auto;
  width: 18px;
  height: 18px;
  -webkit-tap-highlight-color: transparent;
  transform: translate3d(0, 0, 0);
}

.__UIV_SCOPE__ .check:before {
  content: "";
  position: absolute;
  top: -15px;
  left: -15px;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(34, 50, 84, 0.03);
  opacity: 0;
  transition: opacity 0.2s ease;
}

.__UIV_SCOPE__ .check svg {
  position: relative;
  z-index: 1;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke: #c8ccd4;
  stroke-width: 1.5;
  transform: translate3d(0, 0, 0);
  transition: all 0.2s ease;
}

.__UIV_SCOPE__ .check svg path {
  stroke-dasharray: 60;
  stroke-dashoffset: 0;
}

.__UIV_SCOPE__ .check svg polyline {
  stroke-dasharray: 22;
  stroke-dashoffset: 66;
}

.__UIV_SCOPE__ .check:hover:before {
  opacity: 1;
}

.__UIV_SCOPE__ .check:hover svg {
  stroke: var(--accent-color, #a3e583);
}

.__UIV_SCOPE__ #cbx2:checked + .check svg {
  stroke: var(--accent-color, #a3e583);
}

.__UIV_SCOPE__ #cbx2:checked + .check svg path {
  stroke-dashoffset: 60;
  transition: all 0.3s linear;
}

.__UIV_SCOPE__ #cbx2:checked + .check svg polyline {
  stroke-dashoffset: 42;
  transition: all 0.2s linear;
  transition-delay: 0.15s;
}
